168	+/**
169	+ * Briefing builder for the Hermes executor.
170	+ *
171	+ * Reads task context from the already-cloned management repo and produces
172	+ * a briefing scoped to code work only. The wrapper (index.ts) owns all
173	+ * workflow protocol (git, PR, result.json) — Hermes must not attempt any
174	+ * of those actions.
175	+ */
176	+
177	+import { readFileSync, existsSync } from "node:fs";
178	+import { join } from "node:path";
179	+
180	+export interface BriefingOpts {
181	+  workspaceId: string;
182	+  taskId: string;
183	+  featureId: string;
184	+  taskRepoPath: string;
185	+}
186	+
187	+/**
188	+ * Read a section from tasks.md for the given taskId.
189	+ * Returns the content between the ## T<n> heading and the next ## heading.
190	+ */
191	+function readTasksSection(mgmtDir: string, featureId: string, taskId: string): string {
192	+  const tasksPath = join(mgmtDir, "docs", "features", featureId, "tasks.md");
193	+  if (!existsSync(tasksPath)) return `(tasks.md not found at ${tasksPath})`;
194	+
195	+  const content = readFileSync(tasksPath, "utf-8");
196	+  const lines = content.split("\n");
197	+
198	+  const startPattern = new RegExp(`^## ${taskId}\\b`);
199	+  let startIdx = -1;
200	+  for (let i = 0; i < lines.length; i++) {
201	+    if (startPattern.test(lines[i])) {
202	+      startIdx = i;
203	+      break;
204	+    }
205	+  }
206	+
207	+  if (startIdx === -1) return `(section ## ${taskId} not found in tasks.md)`;
208	+
209	+  let endIdx = lines.length;
210	+  for (let i = startIdx + 1; i < lines.length; i++) {
211	+    if (/^## /.test(lines[i])) {
212	+      endIdx = i;
213	+      break;
214	+    }
215	+  }
216	+
217	+  return lines.slice(startIdx, endIdx).join("\n").trim();
218	+}
219	+
