507	--- /dev/null
508	+++ b/runtime/executors/hermes/src/index.ts
509	@@ -0,0 +1,438 @@
510	+/**
511	+ * Hermes executor entrypoint — ABI-conformant.
512	+ *
513	+ * Reads ExecutorInput from environment variables, runs phases 1–5, then
514	+ * post-execution (Phase 6) commits, pushes, opens the impl PR, and writes result.json.
515	+ *
516	+ * Formal ABI env vars (from ExecutorInput):
517	+ *   TASK_ID, FEATURE_ID, WORKSPACE_ID, HANDLE
518	+ *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_BASE_BRANCH, TASK_REPO_BASE_BRANCH
519	+ *   EXECUTOR_WORKDIR, MGMT_REPO_URL
520	+ *   RESULT_PATH
521	+ *   SSH_PRIVATE_KEY, GITHUB_TOKEN
522	+ *
523	+ * Hermes-specific env vars (injected via SubProcessAdapterOpts.extraEnv):
524	+ *   HERMES_INFERENCE_MODEL    — model ID (e.g. deepseek-v4-flash)
525	+ *   HERMES_INFERENCE_PROVIDER — provider (e.g. deepseek)
526	+ *   HERMES_MAX_TURNS          — max tool iterations (default 150)
527	+ *   RAG_MCP_URL               — optional RAG MCP server URL
528	+ *   RAG_MCP_TOKEN             — optional RAG MCP auth token
529	+ *
530	+ * Startup phases:
531	+ *   Phase 1: clone management repo (read-only)
532	+ *   Phase 2: clone implementation repo onto TASK_REPO_BRANCH
533	+ *   Phase 3: write HERMES_HOME/config.yaml (model + optional MCP stanza)
534	+ *   Phase 4: build briefing from mgmt clone
535	+ *   Phase 5: spawn hermes chat in try/finally (recovery fires in finally)
536	+ *   Phase 6: wrapper commits + pushes + opens impl PR + writes result.json [T4]
537	+ */
538	+
539	+import { spawn, execSync } from "node:child_process";
540	+import {
541	+  mkdirSync,
542	+  writeFileSync,
543	+  existsSync,
544	+  rmSync,
545	+} from "node:fs";
546	+import { join, dirname } from "node:path";
547	+import { stringify as yamlStringify } from "yaml";
548	+import type { ExecutorResult } from "@workflow/runtime-abi";
549	+import { runRecovery, type SpawnResult } from "./recovery.js";
550	+import { buildBriefing } from "./briefing.js";
551	+import { resolveSSHKey } from "./resolve-ssh-key.js";
552	+import { buildGitEnv } from "./git-env.js";
553	+
554	+// ── Helpers ────────────────────────────────────────────────────────────────────
555	+
556	+function requireEnv(name: string): string {
557	+  const val = process.env[name];
558	+  if (!val) throw new Error(`Required env var ${name} is not set`);
559	+  return val;
560	+}
561	+
562	+function emit(event: Record<string, unknown>): void {
563	+  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
564	+}
565	+
566	+function writeResult(resultPath: string, result: ExecutorResult): void {
567	+  mkdirSync(dirname(resultPath), { recursive: true });
568	+  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
569	+}
570	+
571	+// ── Phase 1 + 2: repo materialisation ─────────────────────────────────────────
572	+
573	+/**
574	+ * Clone or pull a repo at targetDir on the given branch.
575	+ * If targetDir already contains a valid clone of the same URL,
576	+ * fetch + checkout + pull instead of re-cloning.
577	+ */
578	+export function cloneOrPull(
579	+  url: string,
580	+  targetDir: string,
581	+  branch: string,
582	+  sshKeyPath: string | undefined,
583	+): void {
584	+  const env = buildGitEnv(sshKeyPath);
585	+  const opts = { env, stdio: "pipe" as const };
586	+
587	+  if (existsSync(join(targetDir, ".git"))) {
588	+    let originUrl = "";
589	+    try {
590	+      originUrl = execSync(`git -C "${targetDir}" remote get-url origin`, {
591	+        ...opts, encoding: "utf-8",
592	+      }).trim();
593	+    } catch { /* no remote — fall through to clone */ }
594	+
595	+    if (originUrl === url) {
596	+      execSync(`git -C "${targetDir}" fetch origin`, opts);
597	+      try {
598	+        execSync(`git -C "${targetDir}" checkout -- .`, opts);
599	+      } catch { /* ignore */ }
600	+      try {
601	+        execSync(`git -C "${targetDir}" checkout "${branch}"`, opts);
602	+      } catch {
603	+        execSync(`git -C "${targetDir}" checkout -b "${branch}"`, opts);
604	+      }
605	+      try {
606	+        execSync(`git -C "${targetDir}" pull --ff-only origin "${branch}"`, opts);
607	+      } catch {
608	+        emit({ type: "repo_pull_diverged", dir: targetDir, branch, note: "ff-only failed — using checked-out ref" });
609	+      }
610	+      return;
611	+    }
612	+  }
613	+
614	+  mkdirSync(dirname(targetDir), { recursive: true });
615	+  if (existsSync(targetDir)) {
616	+    rmSync(targetDir, { recursive: true, force: true });
617	+  }
618	+  execSync(`git clone "${url}" "${targetDir}"`, opts);
619	+  try {
620	+    execSync(`git -C "${targetDir}" checkout "${branch}"`, opts);
621	+  } catch {
622	+    execSync(`git -C "${targetDir}" checkout -b "${branch}"`, opts);
623	+  }
624	+}
625	+
626	+/**
627	+ * Materialize the management repo on the task branch.
628	+ * Falls back to main if the task branch is not yet on origin.
629	+ */
630	+export function materializeMgmtRepo(
631	+  mgmtRepoUrl: string,
632	+  mgmtDir: string,
633	+  sshKeyPath: string | undefined,
634	+  taskBranch: string,
635	+): void {
636	+  const env = buildGitEnv(sshKeyPath);
637	+  const opts = { env, stdio: "pipe" as const };
638	+
639	+  const checkoutTaskBranch = (dir: string): void => {
640	+    try {
641	+      execSync(`git -C "${dir}" checkout -B "${taskBranch}" "origin/${taskBranch}"`, opts);
642	+    } catch (taskBranchErr) {
643	+      try {
644	+        execSync(`git -C "${dir}" checkout main`, opts);
645	+      } catch (e) {
646	+        emit({ type: "mgmt_repo_checkout_failed", dir, branch: "main", details: String(e) });
647	+      }
648	+      try {
649	+        execSync(`git -C "${dir}" pull --ff-only origin main`, opts);
650	+      } catch {
651	+        emit({ type: "mgmt_repo_pull_diverged", dir, note: "ff-only failed", task_branch_err: String(taskBranchErr) });
652	+      }
653	+    }
654	+  };
655	+
656	+  if (existsSync(join(mgmtDir, ".git"))) {
657	+    let originUrl = "";
658	+    try {
659	+      originUrl = execSync(`git -C "${mgmtDir}" remote get-url origin`, {
660	+        ...opts, encoding: "utf-8",
661	+      }).trim();
662	+    } catch { /* no remote */ }
663	+
664	+    if (originUrl === mgmtRepoUrl) {
665	+      execSync(`git -C "${mgmtDir}" fetch origin`, opts);
666	+      checkoutTaskBranch(mgmtDir);
667	+      return;
668	+    }
669	+  }
670	+
671	+  mkdirSync(dirname(mgmtDir), { recursive: true });
672	+  if (existsSync(mgmtDir)) {
673	+    rmSync(mgmtDir, { recursive: true, force: true });
674	+  }
675	+  execSync(`git clone "${mgmtRepoUrl}" "${mgmtDir}"`, opts);
676	+  checkoutTaskBranch(mgmtDir);
677	+}
678	+
679	+// ── Phase 3: Hermes config ─────────────────────────────────────────────────────
680	+
681	+export interface HermesConfig {
682	+  provider: string;
683	+  model: string;
684	+  ragMcpUrl?: string;
685	+  ragMcpToken?: string;
686	+}
687	+
688	+/**
689	+ * Write HERMES_HOME/config.yaml with model stanza and optional RAG MCP stanza.
690	+ * No memory stanza — stateless by default (Mem0 is hermes-workspace-memory scope).
691	+ */
692	+export function writeHermesConfig(hermesHome: string, config: HermesConfig): void {
693	+  mkdirSync(hermesHome, { recursive: true });
694	+
695	+  const configObj: Record<string, unknown> = {
696	+    model: {
697	+      provider: config.provider,
698	+      default: config.model,
699	+    },
700	+  };
701	+
702	+  if (config.ragMcpUrl) {
703	+    configObj.mcp_servers = {
704	+      rag: {
705	+        url: config.ragMcpUrl,
706	+        ...(config.ragMcpToken
707	+          ? { headers: { Authorization: `Bearer ${config.ragMcpToken}` } }
708	+          : {}),
709	+      },
710	+    };
711	+  }
712	+
713	+  writeFileSync(join(hermesHome, "config.yaml"), yamlStringify(configObj), "utf-8");
714	+}
715	+
716	+// ── Phase 5: Hermes spawn ──────────────────────────────────────────────────────
717	+
718	+interface HermesSpawnOpts {
719	+  briefing: string;
720	+  hermesHome: string;
721	+  hermesModel: string;
722	+  hermesProvider: string;
723	+  hermesMaxTurns: string;
724	+  taskRepoPath: string;
725	+}
726	+
727	+function spawnHermes(opts: HermesSpawnOpts): Promise<SpawnResult> {
728	+  const {
729	+    briefing,
730	+    hermesHome,
731	+    hermesModel,
732	+    hermesProvider,
733	+    hermesMaxTurns,
734	+    taskRepoPath,
735	+  } = opts;
736	+
737	+  return new Promise((resolve) => {
738	+    const env: NodeJS.ProcessEnv = {
739	+      ...process.env,
740	+      HERMES_HOME: hermesHome,
741	+      HERMES_INFERENCE_MODEL: hermesModel,
742	+      HERMES_INFERENCE_PROVIDER: hermesProvider,
743	+      HERMES_MAX_ITERATIONS: hermesMaxTurns,
744	+      HERMES_YOLO_MODE: "1",
745	+    };
746	+
747	+    const child = spawn(
748	+      "hermes",
749	+      ["chat", "--query", briefing, "--quiet", "--ignore-rules"],
750	+      {
751	+        cwd: taskRepoPath,
752	+        env,
753	+        stdio: ["ignore", "pipe", "pipe"],
754	+      },
755	+    );
756	+
757	+    let stdout = "";
758	+    child.stdout.on("data", (chunk: Buffer) => {
759	+      stdout += chunk.toString();
760	+    });
761	+    child.stderr.on("data", (chunk: Buffer) => {
762	+      process.stderr.write(chunk);
763	+    });
764	+
765	+    child.on("error", (error: Error) => {
766	+      resolve({ stdout, status: null, signal: null, error });
767	+    });
768	+
769	+    child.on("close", (code: number | null, signal: NodeJS.Signals | null) => {
770	+      resolve({ stdout, status: code, signal });
771	+    });
772	+  });
773	+}
774	+
775	+// ── Main ──────────────────────────────────────────────────────────────────────
776	+
777	+async function main(): Promise<void> {
778	+  let taskId: string;
779	+  let featureId: string;
780	+  let workspaceId: string;
781	+  let taskRepoUrl: string;
782	+  let taskRepoBranch: string;
783	+  let taskBaseBranch: string;
784	+  let executorWorkdir: string;
785	+  let mgmtRepoUrl: string;
786	+  let resultPath: string;
787	+  let githubToken: string;
788	+  let sshKeyPath: string | undefined;
789	+
790	+  try {
791	+    taskId = requireEnv("TASK_ID");
792	+    featureId = requireEnv("FEATURE_ID");
793	+    workspaceId = requireEnv("WORKSPACE_ID");
794	+    taskRepoUrl = requireEnv("TASK_REPO_URL");
795	+    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
796	+    taskBaseBranch = process.env.TASK_BASE_BRANCH ?? "main";
797	+    executorWorkdir = requireEnv("EXECUTOR_WORKDIR");
798	+    mgmtRepoUrl = requireEnv("MGMT_REPO_URL");
799	+    resultPath = requireEnv("RESULT_PATH");
800	+    githubToken = process.env.GITHUB_TOKEN ?? "";
801	+    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }).sshKeyPath;
802	+  } catch (e) {
803	+    emit({ type: "executor_fatal", details: (e as Error).message });
804	+    process.exit(1);
805	+  }
806	+
807	+  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
808	+  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
809	+  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
810	+
811	+  const hermesModel = process.env.HERMES_INFERENCE_MODEL ?? "default";
812	+  const hermesProvider = process.env.HERMES_INFERENCE_PROVIDER ?? "openai";
813	+  const hermesMaxTurns = process.env.HERMES_MAX_TURNS ?? "150";
814	+  const ragMcpUrl = process.env.RAG_MCP_URL;
815	+  const ragMcpToken = process.env.RAG_MCP_TOKEN;
816	+
817	+  const implDir = join(executorWorkdir, "impl");
818	+  const mgmtDir = join(executorWorkdir, "mgmt");
819	+  const hermesHome = join(executorWorkdir, "hermes-home");
820	+
821	+  // ── Phase 1: Management repo ───────────────────────────────────────────────
822	+  emit({ type: "phase_start", phase: 1, description: "clone management repo" });
823	+  try {
824	+    materializeMgmtRepo(mgmtRepoUrl, mgmtDir, sshKeyPath, taskBranch);
825	+    process.env.WORKSPACE_ROOT = mgmtDir;
826	+    emit({ type: "phase_done", phase: 1, mgmt_dir: mgmtDir });
827	+  } catch (e) {
828	+    emit({ type: "executor_fatal", task_id: taskId, details: `mgmt repo materialization failed: ${String(e)}` });
829	+    writeResult(resultPath, {
830	+      terminal_status: "failed",
831	+      blocked_reason: `mgmt_repo_materialization_failed: ${String(e)}`,
832	+    });
833	+    process.exit(0);
834	+  }
835	+
836	+  // ── Phase 2: Implementation repo ──────────────────────────────────────────
837	+  emit({ type: "phase_start", phase: 2, description: "clone implementation repo" });
838	+  try {
839	+    cloneOrPull(taskRepoUrl, implDir, taskRepoBranch, sshKeyPath);
840	+    process.env.TASK_REPO_PATH = implDir;
841	+    emit({ type: "phase_done", phase: 2, impl_dir: implDir });
842	+  } catch (e) {
843	+    emit({ type: "executor_fatal", task_id: taskId, details: `impl repo materialization failed: ${String(e)}` });
844	+    writeResult(resultPath, {
845	+      terminal_status: "failed",
846	+      blocked_reason: `impl_repo_materialization_failed: ${String(e)}`,
847	+    });
848	+    process.exit(0);
849	+  }
850	+
851	+  // ── Phase 3: Hermes home + config.yaml ────────────────────────────────────
852	+  emit({ type: "phase_start", phase: 3, description: "write HERMES_HOME/config.yaml" });
853	+  try {
854	+    writeHermesConfig(hermesHome, {
855	+      provider: hermesProvider,
856	+      model: hermesModel,
857	+      ragMcpUrl,
858	+      ragMcpToken,
859	+    });
860	+    process.env.HERMES_HOME = hermesHome;
861	+    emit({ type: "phase_done", phase: 3, hermes_home: hermesHome });
862	+  } catch (e) {
863	+    emit({ type: "executor_fatal", task_id: taskId, details: `hermes config write failed: ${String(e)}` });
864	+    writeResult(resultPath, {
865	+      terminal_status: "failed",
866	+      blocked_reason: `hermes_config_write_failed: ${String(e)}`,
867	+    });
868	+    process.exit(0);
869	+  }
870	+
871	+  // ── Phase 4: Build briefing ────────────────────────────────────────────────
872	+  emit({ type: "phase_start", phase: 4, description: "build briefing" });
873	+  let briefing: string;
874	+  try {
