1010	+export interface SpawnResult {
1011	+  stdout: string;
1012	+  status: number | null;
1013	+  signal: string | null;
1014	+  error?: Error;
1015	+}
1016	+
1017	+export interface RecoveryOpts {
1018	+  spawnResult: SpawnResult | undefined;
1019	+  taskId: string;
