1035	+
1036	+function curlJson(args: string[]): unknown {
1037	+  const result = spawnSync("curl", args, {
1038	+    encoding: "utf-8",
1039	+    stdio: ["ignore", "pipe", "pipe"],
1040	+  });
1041	+  if (result.error) throw result.error;
1042	+  const stdout = result.stdout ?? "";
1043	+  if (!stdout.trim()) throw new Error(`curl returned empty response. stderr: ${result.stderr ?? ""}`);
1044	+  return JSON.parse(stdout);
1045	+}
