1047	+export function parseGitHubCoords(repoUrl: string): { owner: string; repo: string } {
1048	+  const sshMatch = /git@github\.com:([^/]+)\/([^.]+?)(?:\.git)?$/.exec(repoUrl);
1049	+  if (sshMatch) return { owner: sshMatch[1], repo: sshMatch[2] };
1050	+  const httpsMatch = /https?:\/\/github\.com\/([^/]+)\/([^/]+?)(?:\.git)?$/.exec(repoUrl);
1051	+  if (httpsMatch) return { owner: httpsMatch[1], repo: httpsMatch[2] };
1052	+  throw new Error(`Cannot parse GitHub coords from URL: "${repoUrl}"`);
1053	+}
