1151	+      ).trim() || "(no changes detected)";
1152	+    } catch {
1153	+      return "(could not determine changed files)";
1154	+    }
1155	+  })();
1156	+
1157	+  const lines = [
1158	+    `# Handover — ${opts.taskId}`,
1159	+    "",
1160	+    `**Terminal reason:** ${opts.terminalReason}`,
1161	+    `**Branch:** ${opts.taskRepoBranch}`,
1162	+    `**Last commit:** ${opts.lastCommitSha} ${opts.lastCommitMessage}`,
1163	+    `**PR:** ${opts.prUrl ?? "(none opened)"}`,
1164	+    "",
1165	+    "## Files modified in this run",
1166	+    "",
1167	+    "```",
1168	+    filesChanged,
1169	+    "```",
1170	+    "",
1171	+    "## Next agent — read this first",
1172	+    "",
1173	+    "This handover was written by the post-hoc recovery routine.",
