1183	+/**
1184	+ * Run the post-hoc recovery routine.
1185	+ *
1186	+ * No-op when the executor already wrote a valid result.json with
1187	+ * terminal_status "in_review". Otherwise: commits dirty work, pushes,
1188	+ * opens draft PR, writes handover.md, writes blocked result.json.
1189	+ *
1190	+ * Non-throwing — always produces result.json.
1191	+ */
1192	+export async function runRecovery(opts: RecoveryOpts): Promise<void> {
1193	+  const {
1194	+    spawnResult,
1195	+    taskId,
1196	+    featureId,
1197	+    taskRepoBranch,
1198	+    taskRepoPath,
1199	+    taskRepoUrl,
1200	+    githubToken,
1201	+    sshKeyPath,
1202	+    gitAuthorEmail,
1203	+    gitAuthorName,
1204	+    resultPath,
1205	+    taskBaseBranch,
1206	+  } = opts;
1207	+
1208	+  // ── 0. No-op when executor already wrote a valid result ────────────────────
1209	+  if (existsSync(resultPath)) {
1210	+    try {
1211	+      const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as Record<string, unknown>;
