1213	+    } catch { /* fall through to recovery */ }
1214	+  }
1215	+
1216	+  emitRecovery({ step: "start", task_id: taskId, feature_id: featureId });
1217	+
1218	+  let existingBlockedReason: string | undefined;
1219	+  if (existsSync(resultPath)) {
1220	+    try {
1221	+      const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as Record<string, unknown>;
1222	+      if (typeof raw.blocked_reason === "string") existingBlockedReason = raw.blocked_reason;
1223	+    } catch { /* ignore */ }
1224	+  }
1225	+
1226	+  const terminalReason = existingBlockedReason ?? detectTerminalReason(spawnResult);
1227	+
1228	+  // ── 1. Commit dirty working tree ───────────────────────────────────────────
1229	+  let lastCommitSha = "";
1230	+  let lastCommitMessage = "";
1231	+  try {
1232	+    const porcelain = execSync(`git -C "${taskRepoPath}" status --porcelain`, {
1233	+      encoding: "utf-8",
1234	+      stdio: "pipe",
1235	+    }).trim();
1236	+    if (porcelain) {
1237	+      const gitEnv = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
1238	+      execSync(`git -C "${taskRepoPath}" add -A`, { env: gitEnv, stdio: "pipe" });
1239	+      execSync(
1240	+        `git -C "${taskRepoPath}" commit -m "wip(${taskId}): incomplete — agent terminated unexpectedly"`,
1241	+        { env: gitEnv, stdio: "pipe" },
1242	+      );
1243	+    }
1244	+    lastCommitSha = execSync(`git -C "${taskRepoPath}" rev-parse HEAD`, {
1245	+      encoding: "utf-8", stdio: "pipe",
1246	+    }).trim();
1247	+    lastCommitMessage = execSync(`git -C "${taskRepoPath}" log -1 --format=%s`, {
1248	+      encoding: "utf-8", stdio: "pipe",
1249	+    }).trim();
1250	+  } catch (e) {
1251	+    emitRecovery({ step: "commit_dirty_tree", error: String(e) });
1252	+  }
1253	+
1254	+  // ── 2. Push branch (best-effort) ───────────────────────────────────────────
1255	+  try {
1256	+    execSync(`git -C "${taskRepoPath}" push origin "${taskRepoBranch}"`, {
1257	+      env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
1258	+      stdio: "pipe",
1259	+    });
1260	+  } catch (e) {
1261	+    emitRecovery({ step: "push_branch", error: String(e) });
1262	+  }
1263	+
1264	+  // ── 3. Find or open draft PR ───────────────────────────────────────────────
1265	+  let prUrl: string | undefined;
1266	+  if (githubToken && taskRepoUrl) {
1267	+    prUrl = findOrOpenDraftPr({
1268	+      taskRepoUrl, taskRepoBranch, taskId, featureId,
1269	+      githubToken, lastCommitSha, taskBaseBranch,
