1271	+  }
1272	+
1273	+  // ── 4. Write handover.md ───────────────────────────────────────────────────
1274	+  const handoverPath = join(dirname(resultPath), "handover.md");
1275	+  try {
1276	+    writeHandover({
1277	+      handoverPath, taskId, taskRepoBranch, lastCommitSha,
1278	+      lastCommitMessage, terminalReason, prUrl, taskRepoPath,
1279	+    });
1280	+  } catch (e) {
1281	+    emitRecovery({ step: "write_handover", error: String(e) });
1282	+  }
1283	+
1284	+  // ── 5. Write result.json ───────────────────────────────────────────────────
1285	+  try {
1286	+    const result: ExecutorResult = {
1287	+      terminal_status: "blocked",
1288	+      blocked_reason: terminalReason,
1289	+      ...(prUrl ? { pr_url: prUrl } : {}),
1290	+      ...(existsSync(handoverPath) ? { handover_path: handoverPath } : {}),
1291	+    };
1292	+    mkdirSync(dirname(resultPath), { recursive: true });
1293	+    writeFileSync(resultPath, JSON.stringify(result), "utf-8");
1294	+    emitRecovery({ step: "wrote_result", terminal_status: "blocked", blocked_reason: terminalReason });
1295	+  } catch (e) {
1296	+    emitRecovery({ step: "write_result", error: String(e) });
1297	+  }
1298	+}
1299	+
1300	+function detectTerminalReason(spawnResult: SpawnResult | undefined): string {
1301	+  if (!spawnResult) return "executor_crashed";
1302	+  if (spawnResult.error) return "executor_spawn_error";
1303	+  if (spawnResult.signal) return `executor_signal_${spawnResult.signal}`;
1304	+  if (spawnResult.status !== 0) return "executor_crashed";
1305	+  return "result_not_written";
1306	+}
